examples.template:
Column(
    modifier = Modifier
        .fillMaxWidth()
        .verticalScroll(rememberScrollState())
        .imePadding()
        .padding(MonarchTheme.spacing.space4),
    horizontalAlignment = Alignment.CenterHorizontally,
    verticalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space6),
) {
    MonarchText(text = {{brand}}, style = MonarchTextStyle.Heading)
    MonarchCard(modifier = Modifier.widthIn(max = MonarchTheme.spacing.space24 * 5)) {
        Column(verticalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space4)) {
            MonarchText(text = {{title}}, style = MonarchTextStyle.Title, heading = true)
            MonarchText(text = {{description}}, style = MonarchTextStyle.Body)
            MonarchTextField(value = email, onValueChange = { email = it }, label = {{field}})
            MonarchButton(
                text = {{submit}},
                onClick = {},
                modifier = Modifier.fillMaxWidth(),
                variant = MonarchButtonVariant.Primary,
            )
            MonarchText(text = {{footer}}, style = MonarchTextStyle.Caption)
        }
    }
    Row(horizontalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space4)) {
        MonarchLink(text = {{links.0}}, onClick = {}, variant = MonarchLinkVariant.Subtle)
        MonarchLink(text = {{links.1}}, onClick = {}, variant = MonarchLinkVariant.Subtle)
        MonarchLink(text = {{links.2}}, onClick = {}, variant = MonarchLinkVariant.Subtle)
    }
}

